def headers():
    if not OANDA_TOKEN:
        raise RuntimeError(
            "OANDA_TOKEN is not configured"
        )

    return {
        "Authorization":
            f"Bearer {OANDA_TOKEN}"
    }


def iso_utc(dt):
    return (
        dt.astimezone(timezone.utc)
        .isoformat()
        .replace("+00:00", "Z")
    )


def oanda_get(path, params):
    response = requests.get(
        OANDA_URL + path,
        headers=headers(),
        params=params,
        timeout=30,
    )

    if not response.ok:
        raise RuntimeError(
            f"OANDA {response.status_code}: "
            f"{response.text[:500]}"
        )

    return response.json()


def parse_candle(raw):
    if not raw.get("complete", False):
        return None

    mid = raw.get("mid")

    if not mid:
        return None

    return {
        "time":
            datetime.fromisoformat(
                raw["time"].replace(
                    "Z",
                    "+00:00",
                )
            ),
        "open":
            float(mid["o"]),
        "high":
            float(mid["h"]),
        "low":
            float(mid["l"]),
        "close":
            float(mid["c"]),
    }


def fetch_range(start, end):
    data = oanda_get(
        f"/v3/instruments/{INSTRUMENT}/candles",
        {
            "price": "M",
            "granularity": "H1",
            "from": iso_utc(start),
            "to": iso_utc(end),
            "smooth": "false",
            "includeFirst": "true",
        },
    )

    candles = []

    for raw in data.get(
        "candles",
        [],
    ):
        candle = parse_candle(raw)

        if candle is not None:
            candles.append(candle)

    return candles


def fetch_chunked(start, end):
    by_time = {}
    cursor = start

    while cursor < end:
        chunk_end = min(
            cursor
            + timedelta(
                days=H1_CHUNK_DAYS
            ),
            end,
        )

        print(
            f"Fetching H1: "
            f"{cursor.date()} "
            f"-> {chunk_end.date()}",
            flush=True,
        )

        for candle in fetch_range(
            cursor,
            chunk_end,
        ):
            by_time[
                candle["time"]
            ] = candle

        cursor = chunk_end

    candles = list(
        by_time.values()
    )

    candles.sort(
        key=lambda x:
            x["time"]
    )

    return candles


def true_ranges(candles):
    out = []

    for index, candle in enumerate(
        candles
    ):
        if index == 0:
            tr = (
                candle["high"]
                - candle["low"]
            )
        else:
            previous_close = (
                candles[
                    index - 1
                ]["close"]
            )

            tr = max(
                candle["high"]
                - candle["low"],
                abs(
                    candle["high"]
                    - previous_close
                ),
                abs(
                    candle["low"]
                    - previous_close
                ),
            )

        out.append(tr)

    return out


def rma_series(values, length):
    result = [
        None
    ] * len(values)

    if len(values) < length:
        return result

    initial = (
        sum(values[:length])
        / length
    )

    result[
        length - 1
    ] = initial

    previous = initial

    for index in range(
        length,
        len(values),
    ):
        current = (
            (
                previous
                * (
                    length - 1
                )
            )
            + values[index]
        ) / length

        result[index] = current
        previous = current

    return result


def atr_series(candles):
    return rma_series(
        true_ranges(candles),
        ATR_LENGTH,
    )


def read_embedded_csv(text):
    return pd.read_csv(
        io.StringIO(text)
    )


def load_portfolio(text):
    df = read_embedded_csv(
        text
    )

    df["entry_time_utc"] = (
        pd.to_datetime(
            df["entry_time_utc"],
            utc=True,
        )
    )

    df["exit_time_utc"] = (
        pd.to_datetime(
            df["exit_time_utc"],
            utc=True,
        )
    )

    df["result_r"] = (
        pd.to_numeric(
            df["result_r"],
            errors="coerce",
        )
    )

    return df


def load_candidates():
    df = read_embedded_csv(
        CANDIDATES
    )

    numeric_cols = [
        "structure_lookback",
        "maximum_distance_atr",
        "minimum_body_atr",
        "minimum_range_atr",
        "minimum_body_ratio",
        "minimum_close_location",
    ]

    for col in numeric_cols:
        df[col] = pd.to_numeric(
            df[col],
            errors="coerce",
        )

    return df


def build_raw_candidates(
    h1,
    atr,
    max_lookback,
):
    raw = []

    start_index = max(
        ATR_LENGTH,
        max_lookback,
    )

    for index in range(
        start_index,
        len(h1),
    ):
        signal = h1[index]
        previous = h1[
            index - 1
        ]

        current_atr = atr[
            index
        ]

        if (
            current_atr is None
            or current_atr <= 0
        ):
            continue

        previous_body = abs(
            previous["close"]
            - previous["open"]
        )

        current_body = abs(
            signal["close"]
            - signal["open"]
        )

        signal_range = (
            signal["high"]
            - signal["low"]
        )

        if (
            previous_body <= 0
            or current_body <= 0
            or signal_range <= 0
        ):
            continue

        bullish_engulfing = (
            previous["close"]
            < previous["open"]
            and
            signal["close"]
            > signal["open"]
            and
            signal["open"]
            <= previous["close"]
            and
            signal["close"]
            >= previous["open"]
        )

        if not bullish_engulfing:
            continue

        body_ratio = (
            current_body
            / previous_body
        )

        if body_ratio < 1.00:
            continue

        raw.append({
            "index":
                index,
            "time":
                signal["time"],
            "body_ratio":
                body_ratio,
            "body_atr":
                current_body
                / current_atr,
            "range_atr":
                signal_range
                / current_atr,
            "close_location":
                (
                    signal["close"]
                    - signal["low"]
                ) / signal_range,
            "atr":
                current_atr,
        })

    return raw


def structure_distance(
    h1,
    signal,
    lookback,
):
    index = signal[
        "index"
    ]

    previous_lowest = min(
        candle["low"]
        for candle
        in h1[
            index - lookback:
            index
        ]
    )

    return (
        h1[index]["low"]
        - previous_lowest
    ) / signal["atr"]


EXIT_CACHE = {}


def calculate_trade_exit(
    h1,
    signal_index,
):
    if signal_index in EXIT_CACHE:
        return EXIT_CACHE[
            signal_index
        ]

    signal = h1[
        signal_index
    ]

    reference_entry = (
        signal["close"]
    )

    backtest_entry = (
        reference_entry
        + BACKTEST_SLIPPAGE_TICKS
        * TICK_SIZE
    )

    stop = (
        signal["low"]
        - STOP_BUFFER_TICKS
        * TICK_SIZE
    )

    reference_risk = (
        reference_entry
        - stop
    )

    if reference_risk <= 0:
        EXIT_CACHE[
            signal_index
        ] = None
        return None

    target = (
        reference_entry
        + reference_risk
        * REWARD_RISK
    )

    actual_risk = (
        backtest_entry
        - stop
    )

    if actual_risk <= 0:
        EXIT_CACHE[
            signal_index
        ] = None
        return None

    for index in range(
        signal_index + 1,
        len(h1),
    ):
        candle = h1[index]

        stop_hit = (
            candle["low"]
            <= stop
        )

        target_hit = (
            candle["high"]
            >= target
        )

        if not (
            stop_hit
            or target_hit
        ):
            continue

        if (
            stop_hit
            and target_hit
        ):
            distance_to_high = abs(
                candle["high"]
                - candle["open"]
            )

            distance_to_low = abs(
                candle["open"]
                - candle["low"]
            )

            if (
                distance_to_high
                < distance_to_low
            ):
                exit_price = target
                exit_reason = (
                    "TARGET_TIE_FIRST"
                )
            else:
                exit_price = stop
                exit_reason = (
                    "STOP_TIE_FIRST"
                )

        elif target_hit:
            exit_price = target
            exit_reason = "TARGET"

        else:
            exit_price = stop
            exit_reason = "STOP"

        result = {
            "signal_index":
                signal_index,
            "entry_time_utc":
                signal["time"],
            "exit_index":
                index,
            "exit_time_utc":
                candle["time"],
            "reference_entry":
                reference_entry,
            "backtest_entry":
                backtest_entry,
            "stop":
                stop,
            "target":
                target,
            "exit_reason":
                exit_reason,
            "result_r":
                (
                    exit_price
                    - backtest_entry
                ) / actual_risk,
        }

        EXIT_CACHE[
            signal_index
        ] = result

        return result

    EXIT_CACHE[
        signal_index
    ] = None

    return None


def candidate_trades(
    h1,
    raw,
    config,
):
    lookback = int(
        config[
            "structure_lookback"
        ]
    )

    distance = float(
        config[
            "maximum_distance_atr"
        ]
    )

    body_atr = float(
        config[
            "minimum_body_atr"
        ]
    )

    range_atr = (
        None
        if pd.isna(
            config[
                "minimum_range_atr"
            ]
        )
        else float(
            config[
                "minimum_range_atr"
            ]
        )
    )

    body_ratio = float(
        config[
            "minimum_body_ratio"
        ]
    )

    strong_close = (
        None
        if pd.isna(
            config[
                "minimum_close_location"
            ]
        )
        else float(
            config[
                "minimum_close_location"
            ]
        )
    )

    eligible = []

    for signal in raw:
        if (
            signal[
                "body_atr"
            ] < body_atr
        ):
            continue

        if (
            range_atr is not None
            and signal[
                "range_atr"
            ] < range_atr
        ):
            continue

        if (
            signal[
                "body_ratio"
            ] < body_ratio
        ):
            continue

        if (
            strong_close is not None
            and signal[
                "close_location"
            ] < strong_close
        ):
            continue

        if (
            structure_distance(
                h1,
                signal,
                lookback,
            )
            > distance
        ):
            continue

        eligible.append(
            signal
        )

    trades = []
    position_exit_index = -1

    for signal in eligible:
        index = signal[
            "index"
        ]

        if (
            index
            < position_exit_index
        ):
            continue

        trade = calculate_trade_exit(
            h1,
            index,
        )

        if trade is None:
            break

        trades.append(
            dict(trade)
        )

        position_exit_index = (
            trade[
                "exit_index"
            ]
        )

    return trades


def trades_to_df(
    trades,
    label,
):
    rows = []

    for trade in trades:
        rows.append({
            "instrument":
                "USD_JPY",
            "side":
                "BUY",
            "strategy":
                label,
            "entry_time_utc":
                trade[
                    "entry_time_utc"
                ],
            "exit_time_utc":
                trade[
                    "exit_time_utc"
                ],
            "reference_entry":
                trade[
                    "reference_entry"
                ],
            "backtest_entry":
                trade[
                    "backtest_entry"
                ],
            "stop":
                trade["stop"],
            "target":
                trade["target"],
            "exit_reason":
                trade[
                    "exit_reason"
                ],
            "result_r":
                trade[
                    "result_r"
                ],
            "reward_risk":
                REWARD_RISK,
        })

    return pd.DataFrame(
        rows
    )


def stats(df):
    values = (
        df[
            "result_r"
        ]
        .astype(float)
    )

    winners = values[
        values > 0
    ]

    losers = values[
        values < 0
    ]

    gross_profit = (
        winners.sum()
    )

    gross_loss = abs(
        losers.sum()
    )

    if gross_loss > 0:
        pf = (
            gross_profit
            / gross_loss
        )
    elif gross_profit > 0:
        pf = 999.0
    else:
        pf = 0.0

    total_r = (
        values.sum()
    )

    return {
        "trades":
            len(df),
        "winners":
            len(winners),
        "losers":
            len(losers),
        "win_rate":
            (
                len(winners)
                / len(df)
                * 100.0
                if len(df)
                else 0.0
            ),
        "profit_factor":
            pf,
        "total_r":
            total_r,
        "expectancy_r":
            (
                total_r
                / len(df)
                if len(df)
                else 0.0
            ),
    }


def compound(
    df,
    starting_balance=100.0,
    risk_percent=0.01,
):
    records = (
        df.reset_index(
            drop=True
        )
        .to_dict(
            "records"
        )
    )

    events = []

    for index, trade in enumerate(
        records
    ):
        entry_time = (
            pd.Timestamp(
                trade[
                    "entry_time_utc"
                ]
            ).to_pydatetime()
        )

        exit_time = (
            pd.Timestamp(
                trade[
                    "exit_time_utc"
                ]
            ).to_pydatetime()
        )

        events.append((
            entry_time,
            1,
            "ENTRY",
            index,
        ))

        events.append((
            exit_time,
            0,
            "EXIT",
            index,
        ))

    events.sort(
        key=lambda x:
            (
                x[0],
                x[1],
            )
    )

    balance = float(
        starting_balance
    )

    risk_at_entry = {}

    peak = balance
    max_dd_pct = 0.0

    for (
        event_time,
        priority,
        event_type,
        index,
    ) in events:
        trade = records[
            index
        ]

        if event_type == "ENTRY":
            risk_at_entry[
                index
            ] = (
                balance
                * risk_percent
            )

        else:
            risk_amount = (
                risk_at_entry.get(
                    index
                )
            )

            if risk_amount is None:
                continue

            balance += (
                risk_amount
                * float(
                    trade[
                        "result_r"
                    ]
                )
            )

            peak = max(
                peak,
                balance,
            )

            if peak > 0:
                drawdown = (
                    (
                        balance
                        - peak
                    )
                    / peak
                    * 100.0
                )

                max_dd_pct = min(
                    max_dd_pct,
                    drawdown,
                )

    return {
        "ending_balance":
            balance,
        "return_pct":
            (
                balance
                / starting_balance
                - 1.0
            )
            * 100.0,
        "max_closed_equity_dd_pct":
            max_dd_pct,
    }


def replace_usdjpy_buy(
    current,
    candidate_df,
):
    start = (
        current[
            "entry_time_utc"
        ].min()
    )

    end = (
        current[
            "entry_time_utc"
        ].max()
    )

    kept = current[
        ~(
            (
                current[
                    "instrument"
                ] == "USD_JPY"
            )
            &
            (
                current[
                    "side"
                ] == "BUY"
            )
        )
    ].copy()

    incoming = candidate_df[
        (
            candidate_df[
                "entry_time_utc"
            ] >= start
        )
        &
        (
            candidate_df[
                "entry_time_utc"
            ] <= end
        )
    ].copy()

    portfolio = pd.concat(
        [
            kept,
            incoming,
        ],
        ignore_index=True,
    )

    portfolio = (
        portfolio.sort_values(
            [
                "entry_time_utc",
                "exit_time_utc",
                "instrument",
                "side",
            ]
        )
        .reset_index(
            drop=True
        )
    )

    return (
        portfolio,
        incoming,
    )


def metrics_row(
    window,
    label,
    portfolio,
    incoming,
    config=None,
):
    portfolio_stats = stats(
        portfolio
    )

    portfolio_compound = compound(
        portfolio
    )

    pair_stats = stats(
        incoming
    )

    row = {
        "window":
            window,
        "candidate":
            label,
        "portfolio_trades":
            portfolio_stats[
                "trades"
            ],
        "portfolio_win_rate":
            portfolio_stats[
                "win_rate"
            ],
        "portfolio_pf":
            portfolio_stats[
                "profit_factor"
            ],
        "portfolio_total_r":
            portfolio_stats[
                "total_r"
            ],
        "portfolio_expectancy_r":
            portfolio_stats[
                "expectancy_r"
            ],
        "ending_balance_1pct":
            portfolio_compound[
                "ending_balance"
            ],
        "return_pct_1pct":
            portfolio_compound[
                "return_pct"
            ],
        "max_closed_equity_dd_pct":
            portfolio_compound[
                "max_closed_equity_dd_pct"
            ],
        "usdjpy_buy_trades":
            pair_stats[
                "trades"
            ],
        "usdjpy_buy_pf":
            pair_stats[
                "profit_factor"
            ],
        "usdjpy_buy_total_r":
            pair_stats[
                "total_r"
            ],
        "usdjpy_buy_expectancy_r":
            pair_stats[
                "expectancy_r"
            ],
    }

    if config is not None:
        for key in [
            "structure_lookback",
            "maximum_distance_atr",
            "minimum_body_atr",
            "minimum_range_atr",
            "minimum_body_ratio",
            "minimum_close_location",
            "trades",
            "profit_factor",
            "total_r",
            "expectancy_r",
            "max_drawdown_r",
            "minimum_era_pf_5_plus",
            "worst_rolling_3y_pf",
            "last_5y_trades",
            "last_5y_pf",
            "last_5y_r",
            "last_2y_trades",
            "last_2y_pf",
            "last_2y_r",
        ]:
            row[
                f"standalone_{key}"
            ] = config.get(
                key
            )

    return row


def current_baseline_row(
    window,
    current,
):
    current_usdjpy = current[
        (
            current[
                "instrument"
            ] == "USD_JPY"
        )
        &
        (
            current[
                "side"
            ] == "BUY"
        )
    ].copy()

    return metrics_row(
        window,
        "CURRENT_LIVE_USDJPY",
        current,
        current_usdjpy,
        None,
    )


def run_research():
    try:
        STATUS.update({
            "state":
                "loading",
            "message":
                "Loading embedded portfolio baselines and candidate set",
        })

        base5 = load_portfolio(
            BASE5
        )

        base2 = load_portfolio(
            BASE2
        )

        candidates = (
            load_candidates()
        )

        overall_start = min(
            base5[
                "entry_time_utc"
            ].min(),
            base2[
                "entry_time_utc"
            ].min(),
        ).to_pydatetime()

        overall_end = max(
            base5[
                "entry_time_utc"
            ].max(),
            base2[
                "entry_time_utc"
            ].max(),
        ).to_pydatetime()

        max_lookback = int(
            candidates[
                "structure_lookback"
            ].max()
        )

        STATUS.update({
            "state":
                "fetching_h1",
            "message":
                "Fetching USD/JPY H1 data for candidate recreation",
            "candidate_count":
                len(candidates),
        })

        current_completed_hour = (
            datetime.now(timezone.utc)
            .replace(
                minute=0,
                second=0,
                microsecond=0,
            )
        )

        fetch_end = min(
            overall_end
            + timedelta(
                days=45
            ),
            current_completed_hour,
        )

        h1 = fetch_chunked(
            overall_start
            - timedelta(
                days=H1_WARMUP_DAYS
            ),
            fetch_end,
        )

        if not h1:
            raise RuntimeError(
                "No H1 candles returned"
            )

        atr = atr_series(
            h1
        )

        raw = build_raw_candidates(
            h1,
            atr,
            max_lookback,
        )

        STATUS.update({
            "state":
                "running",
            "message":
                "Recreating candidates and testing portfolio substitutions",
            "raw_candidates":
                len(raw),
            "completed_candidates":
                0,
        })

        rows_5y = [
            current_baseline_row(
                "5Y",
                base5,
            )
        ]

        rows_2y = [
            current_baseline_row(
                "2Y",
                base2,
            )
        ]

        trade_exports = []

        for number, (_, config) in enumerate(
            candidates.iterrows(),
            start=1,
        ):
            label = str(
                config[
                    "label"
                ]
            )

            trades = candidate_trades(
                h1,
                raw,
                config,
            )

            candidate_df = (
                trades_to_df(
                    trades,
                    label,
                )
            )

            if len(
                candidate_df
            ):
                candidate_df[
                    "entry_time_utc"
                ] = pd.to_datetime(
                    candidate_df[
                        "entry_time_utc"
                    ],
                    utc=True,
                )

                candidate_df[
                    "exit_time_utc"
                ] = pd.to_datetime(
                    candidate_df[
                        "exit_time_utc"
                    ],
                    utc=True,
                )

            portfolio5, incoming5 = (
                replace_usdjpy_buy(
                    base5,
                    candidate_df,
                )
            )

            portfolio2, incoming2 = (
                replace_usdjpy_buy(
                    base2,
                    candidate_df,
                )
            )

            rows_5y.append(
                metrics_row(
                    "5Y",
                    label,
                    portfolio5,
                    incoming5,
                    config,
                )
            )

            rows_2y.append(
                metrics_row(
                    "2Y",
                    label,
                    portfolio2,
                    incoming2,
                    config,
                )
            )

            export = (
                candidate_df.copy()
            )

            export[
                "candidate"
            ] = label

            trade_exports.append(
                export
            )

            STATUS[
                "completed_candidates"
            ] = number

            print(
                f"Candidate "
                f"{number}/"
                f"{len(candidates)}: "
                f"{label}",
                flush=True,
            )

        five = pd.DataFrame(
            rows_5y
        )

        two = pd.DataFrame(
            rows_2y
        )

        # Rank candidate rows by ending balance first, then total R,
        # then PF. Keep current live row for direct comparison.
        current5 = five[
            five[
                "candidate"
            ] == "CURRENT_LIVE_USDJPY"
        ]

        candidates5 = five[
            five[
                "candidate"
            ] != "CURRENT_LIVE_USDJPY"
        ].sort_values(
            [
                "ending_balance_1pct",
                "portfolio_total_r",
                "portfolio_pf",
            ],
            ascending=[
                False,
                False,
                False,
            ],
        )

        five = pd.concat(
            [
                current5,
                candidates5,
            ],
            ignore_index=True,
        )

        current2 = two[
            two[
                "candidate"
            ] == "CURRENT_LIVE_USDJPY"
        ]

        candidates2 = two[
            two[
                "candidate"
            ] != "CURRENT_LIVE_USDJPY"
        ].sort_values(
            [
                "ending_balance_1pct",
                "portfolio_total_r",
                "portfolio_pf",
            ],
            ascending=[
                False,
                False,
                False,
            ],
        )

        two = pd.concat(
            [
                current2,
                candidates2,
            ],
            ignore_index=True,
        )

        five.to_csv(
            os.path.abspath(
                OUTPUT_5Y
            ),
            index=False,
        )

        two.to_csv(
            os.path.abspath(
                OUTPUT_2Y
            ),
            index=False,
        )

        if trade_exports:
            all_trades = pd.concat(
                trade_exports,
                ignore_index=True,
            )

            all_trades[
                "entry_time_utc"
            ] = (
                all_trades[
                    "entry_time_utc"
                ]
                .dt.strftime(
                    "%Y-%m-%dT%H:%M:%SZ"
                )
            )

            all_trades[
                "exit_time_utc"
            ] = (
                all_trades[
                    "exit_time_utc"
                ]
                .dt.strftime(
                    "%Y-%m-%dT%H:%M:%SZ"
                )
            )

            all_trades.to_csv(
                os.path.abspath(
                    OUTPUT_CANDIDATE_TRADES
                ),
                index=False,
            )

        STATUS.update({
            "state":
                "complete",
            "message":
                "USD/JPY portfolio replacement shootout complete",
            "candidate_count":
                len(candidates),
            "outputs": {
                "5y":
                    OUTPUT_5Y,
                "2y":
                    OUTPUT_2Y,
                "candidate_trades":
                    OUTPUT_CANDIDATE_TRADES,
            },
        })

        print()
        print(
            "=" * 100
        )
        print(
            "USD/JPY PORTFOLIO REPLACEMENT SHOOTOUT COMPLETE"
        )
        print(
            "=" * 100
        )
        print()
        print(
            "5Y CURRENT + TOP 15 CANDIDATES"
        )
        print(
            five.head(
                16
            ).to_string(
                index=False
            ),
            flush=True,
        )
        print()
        print(
            "2Y CURRENT + TOP 15 CANDIDATES"
        )
        print(
            two.head(
                16
            ).to_string(
                index=False
            ),
            flush=True,
        )

    except Exception as error:
        STATUS.update({
            "state":
                "error",
            "message":
                str(error),
        })

        print(
            "ERROR:",
            error,
            flush=True,
        )


